// Editorial descriptions of self-reported habits, not diagnoses or norm-based labels.
const readings = [
 [
  {title:'熟悉的经验更让你踏实',brief:'偏爱具体、熟悉的体验',description:'你更关心一件事的实际用途，愿意把熟悉的方法用顺手。面对新点子，你通常要先看到它与现实的联系，才有兴趣继续了解。',summary:'你比较相信亲身试过的东西，做选择时会先看它能不能解决眼前的问题。',tip:'遇到陌生想法时，可以先试一个小部分，再决定自己想了解多少。'},
  {title:'新鲜感与实用性都想照顾',brief:'愿意尝新，也看重实际用途',description:'你会同时考虑想法的趣味和它在当下的实际用途。有时愿意绕远路看看风景，有时宁可用熟悉的方法省点力气。',summary:'你会被新东西吸引，也懂得什么时候回到熟悉的做法。',tip:'留意哪些新体验让你愿意持续投入，兴趣往往藏在那里。'},
  {title:'容易被新想法吸引',brief:'喜欢琢磨新想法',description:'一个不同的解释、一段意外的联想，常能让你多想一会儿。你愿意给事情保留多种解释，也容易从画面、故事或细节里获得感受。',summary:'你对新接触的想法有好奇心，常会在别人已经翻篇时继续琢磨另一种可能。',tip:'灵感多的时候，挑一个最想做的先试起来，会比同时铺开更轻松。'},
 ],
 [
  {title:'需要能呼吸的安排',brief:'喜欢灵活安排自己的节奏',description:'你喜欢留有余地的安排，往往边做边调整。感兴趣的事情容易让你投入，枯燥的开头和收尾通常需要多一点推动。',summary:'你喜欢给自己留调整的空间，做事更依赖当时的状态和兴趣。',tip:'给重要的事定一个很小的开头，再留一个明确的收尾提醒。'},
  {title:'重要的事有安排，小事留弹性',brief:'有计划，也能临时调整',description:'你愿意把该交代的事情处理好，也重视生活里的自由时间。对你来说，有几个清楚的节点，比一份密密麻麻的日程更有用。',summary:'你通常会守住重要的约定，同时给具体做法留些余地。',tip:'提前分清哪些必须按时完成，哪些可以随情况调整，会更省心。'},
  {title:'答应的事，希望有个交代',brief:'愿意认真准备并把事情做完',description:'你做事时会惦记进度、细节和最后的交接。把事情理清楚会让你安心，也让别人比较容易放心把任务交给你。',summary:'你习惯把要紧的事提前理顺，答应以后也会惦记着把它做完。',tip:'有些小事做到够用就可以，把精力留给真正重要的部分。'},
 ],
 [
  {title:'先熟悉，再慢慢打开',brief:'享受安静和独处',description:'你更喜欢留一点自己的空间，在熟悉的人面前才容易放松。你更享受一对一的交谈，或者安静做喜欢的事。',summary:'独处和熟悉的关系更容易让你恢复精力，你喜欢按自己的节奏参与相处。',tip:'想参与的时候，可以先找一个人聊起来，慢慢找到舒服的节奏。'},
  {title:'热闹可以，安静也需要',brief:'能参与互动，也需要自己的时间',description:'你会按场合选择参与的方式，愿意交流时主动一些，想安静时就留些自己的空间。聊得来时会主动一些，累了以后也愿意退回来，给自己留点安静。',summary:'你能享受交流，也需要属于自己的安静时间，通常会看场合决定参与多少。',tip:'安排社交时，也给自己留一段可以自由支配的时间。'},
  {title:'在互动里更容易来劲',brief:'愿意主动交流和表达',description:'你比较容易主动搭话、表达想法，也愿意走进正在发生的事情里。一个回应、一场讨论或一次共同体验，往往能让你的兴致更高。',summary:'你愿意先开口，也容易从交流和现场的回应中获得动力。',tip:'聊得投入时偶尔停一下，给慢热的人一点接话的时间。'},
 ],
 [
  {title:'重要的事，愿意自己想清楚',brief:'相处时保留判断和边界',description:'你对人和事比较审慎，信任需要慢慢建立。遇到分歧，你愿意把理由说清楚，也希望自己的意见得到认真对待。',summary:'你有自己的判断，关系再近，也希望重要的选择能由自己想清楚。',tip:'表达不同意见时，把具体原因说出来，比猜测对方的动机更容易谈下去。'},
  {title:'愿意体谅，也会守住自己的位置',brief:'兼顾别人的处境与自己的需要',description:'你愿意理解别人的处境，同时会认真考虑自己能投入多少。关系里既需要互相照顾，也需要把各自的要求说清楚。',summary:'你愿意照顾别人的处境，也会考虑一件事对自己是否公平。',tip:'有分歧时，把愿意调整的部分和需要坚持的部分分开说，彼此会更清楚。'},
  {title:'会把别人的感受放进考虑里',brief:'愿意体谅和支持身边的人',description:'你容易留意到别人是否为难，愿意先理解、再回应。相处时你珍惜信任和合作，也可能因为在意别人的期待而答应得太快。',summary:'你会把别人的感受放在心上，常愿意多听一点、多帮一点。',tip:'答应帮忙前，也确认一下自己的时间和精力够不够。'},
 ],
 [
  {title:'事情乱一点，也能慢慢处理',brief:'遇到波折时比较沉得住气',description:'面对变化或小失误，你通常能先稳住自己，把事情一件件处理。你能把注意力慢慢带回眼前，逐渐回到自己的节奏。',summary:'遇到波折时，你通常能先稳住自己，逐步处理好事情，再回到平时的节奏。',tip:'需要支持时，可以直接说出来，让信任的人和你一起分担。'},
  {title:'会在意，也有自己的恢复办法',brief:'有情绪起伏，也有恢复的办法',description:'等待结果的事情会让你挂心，被评价时也可能反复想一会儿。休息、聊一聊或把事情做清楚，通常能帮助你回到平时的状态。',summary:'你会在意结果和别人的回应，也通常能找到让自己缓过来的办法。',tip:'想太多时，先分清现在能做什么，剩下的给它一点时间。'},
  {title:'很多事情会在心里多停留一会儿',brief:'对压力和评价较敏感',description:'重要的结果、别人的语气或突发变化，容易在你心里停留得久一些。等待答案时，你可能已经把几种令人担心的情况想过一遍，需要更多空间来安顿情绪。',summary:'你对压力和他人的回应比较敏感，事情过去以后，有时还需要一点时间才能放下。',tip:'担心很强时，先停下来休息一下，再找信任的人把具体担心说出来。'},
 ],
];
export function describePersonality(scores){
 const dimensions=traits.map((trait,index)=>{
  const side=scores[index]<35?'low':scores[index]>65?'high':'middle';
  return {...readings[index][{low:0,middle:1,high:2}[side]],name:trait.name,index,score:scores[index],side};
 });
 const emphasized=[...dimensions].sort((a,b)=>Math.abs(b.score-50)-Math.abs(a.score-50)||a.index-b.index);
 const balanced=emphasized[0].side==='middle';
 let summary=balanced?'你会根据事情的重要程度和相处对象调整自己的做法：有时愿意主动尝试，有时更想留在熟悉的节奏里。你的习惯会随具体事情和相处对象展开。':emphasized.slice(0,2).map(d=>d.summary).join('');
 if(!balanced&&scores[0]>65&&scores[1]<35)summary+='点子常常比安排先来，真正让你感兴趣的事，会比一份详细计划更能推动你开始。';
 else if(!balanced&&scores[1]>65&&scores[2]<35)summary+='你习惯先把事情准备好，再用行动让别人放心，也享受安静做事的过程。';
 else if(!balanced&&scores[3]>65&&scores[4]>65)summary+='你很在乎关系里的回应，也容易把别人的情绪揽到自己身上，偶尔需要把注意力收回来。';
 return {summary,tip:emphasized[0].tip,dimensions};
}
